import{_ as s,k as i,a6 as t,j as a}from"./chunks/framework.W_BvR9CP.js";const p=JSON.parse('{"title":"v1.35.0-RC.2","description":"The changelog for v1.35.0-RC.2.","frontmatter":{"title":"v1.35.0-RC.2","page_title":"v1.35.0-RC.2 Changelog","description":"The changelog for v1.35.0-RC.2.","category":"Pre-Releases","mentions":["8Crafter"]},"headers":[{"level":2,"title":"Changes","slug":"changes","link":"#changes","children":[{"level":3,"title":"UIs","slug":"uis","link":"#uis","children":[]}]},{"level":2,"title":"Fixes","slug":"fixes","link":"#fixes","children":[{"level":3,"title":"Commands","slug":"commands","link":"#commands","children":[]},{"level":3,"title":"Items","slug":"items","link":"#items","children":[{"level":4,"title":"Editor Stick","slug":"editor-stick","link":"#editor-stick","children":[]}]},{"level":3,"title":"Settings","slug":"settings","link":"#settings","children":[]},{"level":3,"title":"UIs","slug":"uis-1","link":"#uis-1","children":[]}]},{"level":2,"title":"Technical Fixes","slug":"technical-fixes","link":"#technical-fixes","children":[{"level":3,"title":"Permanent Event Subscriptions","slug":"permanent-event-subscriptions","link":"#permanent-event-subscriptions","children":[]}]}],"relativePath":"changelogs/v1.35.0-rc.2.md","filePath":"changelogs/v1.35.0-rc.2.md"}'),n={name:"changelogs/v1.35.0-rc.2.md"};function l(r,e,h,o,c,d){return a(),i("div",null,e[0]||(e[0]=[t('<h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><h3 id="uis" tabindex="-1">UIs <a class="header-anchor" href="#uis" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Added a delete button to the submenu of the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu to manage a specific event subscription.</li><li>Added a move button to the submenu of the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu to manage a specific event subscription, this allows for changing the execution order of event subscriptions, event subscriptions at the top of the list (lower index) will be executed first.</li><li>Added a refresh button to the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu.</li><li>Added a statistics button to the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu.</li><li>The submenu of the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu to manage a specific event subscription now displays the event subscription&#39;s execution order.</li><li>The edit code button for the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu now automatically reinitializes the event subscription when the code is edited.</li><li>When enabling or disabling an event subscription in the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu, the event subscription will be automatically initialized or deinitialized, respectively, so that it is enabled or disabled immediately, instead of only once the event subscriptions are reloaded.</li><li>The <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu now shows the total number of event subscriptions in each category.</li><li>The submenu of the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu to choose between the before and after events now shows the total number of event subscriptions in each category.</li><li>The refresh button for the submenu of the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu to choose between the before and after events now refreshes the displayed number of event subscriptions in each category instead of throwing an error.</li><li>The submenu of the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu to manage the event subscriptions on a specific event now automatically refreshes after creating an event subscription (only for the person who created the event subscription).</li><li>The submenu of the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu to manage the event subscriptions on a specific event is no longer sorted, so as to make the event subscriptions be ordered by their execution order.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Fixed a bug where the <code class="shiki"><span>scale</span></code>, <code class="shiki"><span>scalex</span></code>, <code class="shiki"><span>scaley</span></code>, and <code class="shiki"><span>scalez</span></code> subcommands for the <a href="./../commands-list/--expandselection.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\expandselection</span></code></a> command just scaled the pos1 position by the specified amount instead of scaling the distance between the pos1 and pos2 positions from the center of the selection.</li></ul><h3 id="items" tabindex="-1">Items <a class="header-anchor" href="#items" aria-label="Permalink to &quot;Items&quot;">​</a></h3><h4 id="editor-stick" tabindex="-1">Editor Stick <a class="header-anchor" href="#editor-stick" aria-label="Permalink to &quot;Editor Stick&quot;">​</a></h4><ul><li>Fixed a bug where the 3 editor stick types would set the sign text color on the opposite side of what was specified. (ANDEXDB-63)</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Fixed a bug where the <a href="./../settings/ui/menu-configurations/main-menu/main-menu-settings.html">Main Menu Settings</a> menu was accessing the player menu config (<a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.ui.menus.playerMenu.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">ui</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">menus</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">playerMenu</span></code></a>) instead of the main menu config (<a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.ui.menus.mainMenu.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">ui</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">menus</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">mainMenu</span></code></a>).</li></ul><h3 id="uis-1" tabindex="-1">UIs <a class="header-anchor" href="#uis-1" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Fixed a bug where the submenu of the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu to edit the event subscriptions on a specific event used the grid menu form style instead of the medium form style.</li></ul><h2 id="technical-fixes" tabindex="-1">Technical Fixes <a class="header-anchor" href="#technical-fixes" aria-label="Permalink to &quot;Technical Fixes&quot;">​</a></h2><h3 id="permanent-event-subscriptions" tabindex="-1">Permanent Event Subscriptions <a class="header-anchor" href="#permanent-event-subscriptions" aria-label="Permalink to &quot;Permanent Event Subscriptions&quot;">​</a></h3><ul><li>Fixed a bug where subscriptions to the <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/_internal_.andexdbAfterEvents.html#modifiedchatmessagesend" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">andexdb</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">afterEvents</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modifiedChatMessageSend</span></code></a> event were actually subscribed to its <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/_internal_.andexdbBeforeEvents.html#modifiedchatmessagesend" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">before</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;"> event</span></code></a> variant instead.</li><li>Fixed a bug where the <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/_internal_.SubscribedEvent.html#creationtime" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">SubscribedEvent</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">prototype</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">creationTime</span></code></a> getter returned <code class="shiki"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">NaN</span></code>, causing all the places where an event subscription&#39;s creation time was displayed to show <code class="shiki"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">NaN</span></code>.</li></ul>',16)]))}const m=s(n,[["render",l]]);export{p as __pageData,m as default};
